-- ----------------------------
-- Table structure for interview_process
-- ----------------------------
DROP TABLE IF EXISTS `interview_process`;
CREATE TABLE `interview_process`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '流程ID',
  `resume_id` bigint(20) NOT NULL COMMENT '简历ID',
  `job_id` bigint(20) NOT NULL COMMENT '职位ID',
  `current_stage` tinyint(4) NOT NULL DEFAULT 0 COMMENT '当前阶段（0：简历筛选，1：初试，2：复试，3：终试，4：offer，5：已入职，6：已拒绝）',
  `next_stage_time` datetime NULL DEFAULT NULL COMMENT '下一阶段时间',
  `interviewer_id` bigint(20) NULL DEFAULT NULL COMMENT '面试官ID',
  `interviewer_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '面试官姓名',
  `status` tinyint(4) NOT NULL DEFAULT 0 COMMENT '状态（0：进行中，1：已完成，2：已取消）',
  `created_time` datetime NOT NULL COMMENT '创建时间',
  `updated_time` datetime NOT NULL COMMENT '更新时间',
  `is_deleted` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否删除（0：否，1：是）',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_resume_id`(`resume_id`) USING BTREE,
  INDEX `idx_resume_id`(`resume_id`) USING BTREE,
  INDEX `idx_job_id`(`job_id`) USING BTREE,
  INDEX `idx_interviewer_id`(`interviewer_id`) USING BTREE,
  CONSTRAINT `fk_process_job_id` FOREIGN KEY (`job_id`) REFERENCES `job` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_process_resume_id` FOREIGN KEY (`resume_id`) REFERENCES `resume` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '面试流程表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of interview_process
-- ----------------------------

-- ----------------------------
-- Table structure for interview_record
-- ----------------------------
DROP TABLE IF EXISTS `interview_record`;
CREATE TABLE `interview_record`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `process_id` bigint(20) NOT NULL COMMENT '流程ID',
  `resume_id` bigint(20) NOT NULL COMMENT '简历ID',
  `job_id` bigint(20) NOT NULL COMMENT '职位ID',
  `stage` tinyint(4) NOT NULL COMMENT '面试阶段（1：初试，2：复试，3：终试）',
  `interview_time` datetime NOT NULL COMMENT '面试时间',
  `interviewer_id` bigint(20) NOT NULL COMMENT '面试官ID',
  `interviewer_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '面试官姓名',
  `interview_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '面试类型（现场/视频/电话）',
  `location` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '面试地点',
  `result` tinyint(4) NOT NULL DEFAULT 0 COMMENT '面试结果（0：待评估，1：通过，2：未通过）',
  `comments` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '面试评语',
  `created_time` datetime NOT NULL COMMENT '创建时间',
  `updated_time` datetime NOT NULL COMMENT '更新时间',
  `is_deleted` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否删除（0：否，1：是）',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_process_id_stage`(`process_id`, `stage`) USING BTREE,
  INDEX `idx_process_id`(`process_id`) USING BTREE,
  INDEX `idx_job_id`(`job_id`) USING BTREE,
  INDEX `idx_interviewer_id`(`interviewer_id`) USING BTREE,
  INDEX `idx_stage`(`stage`) USING BTREE,
  INDEX `fk_record_resume_id`(`resume_id`) USING BTREE,
  CONSTRAINT `fk_record_job_id` FOREIGN KEY (`job_id`) REFERENCES `job` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_record_process_id` FOREIGN KEY (`process_id`) REFERENCES `interview_process` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_record_resume_id` FOREIGN KEY (`resume_id`) REFERENCES `resume` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 9 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '面试记录表' ROW_FORMAT = Dynamic;

