-- ----------------------------
-- Procedure structure for sum_add
-- ----------------------------
DROP PROCEDURE IF EXISTS `sum_add`;
delimiter ;;
CREATE PROCEDURE `sum_add`(in maxN int)
BEGIN
	declare i int default 1;
	declare sum int default 0;
	while i<=maxN DO
	set sum = sum +i;
	set i = i +1;
	end while;
	SELECT sum;
end
;;
delimiter ;

SET FOREIGN_KEY_CHECKS = 1;
